def second_largest(xs: List[int]) -> int:
    def _find_second_largest(xs: List[int], factor: int) -> int:
        if len(xs) == 0:
            return None
        elif len(xs) < factor:
            return None
        elif len(xs) == factor:
            return max(xs)
